#[inline]
unsafe fn aptx_qmf_polyphase_analysis(
    mut signal: *mut aptx_filter_signal,
    mut coeffs: *const [int32_t; 16],
    mut shift: c_uint,
    mut samples: *const int32_t,
    mut low_subband_output: *mut int32_t,
    mut high_subband_output: *mut int32_t,
) {
    let s0 = signal;
    // SAFETY: `signal` points to an array of at least `NB_FILTERS` elements; this function only accesses element 1 when `NB_FILTERS == 2` as in the original code.
    let s1 = unsafe { signal.add(1) };

    let c0 = coeffs;
    // SAFETY: `coeffs` points to an array of at least `NB_FILTERS` coefficient blocks; this function only accesses element 1 when `NB_FILTERS == 2` as in the original code.
    let c1 = unsafe { coeffs.add(1) };

    // SAFETY: `samples` points to at least `NB_FILTERS` input samples; indices 1 and 0 match the original loop for `NB_FILTERS == 2`.
    let sample1 = unsafe { *samples.add(1) };
    // SAFETY: `samples` points to at least `NB_FILTERS` input samples; index 0 is in-bounds as in the original code.
    let sample0 = unsafe { *samples.add(0) };

    aptx_qmf_filter_signal_push(s0, sample1);
    let sub0 = aptx_qmf_convolution(
        s0,
        &raw const *c0 as *const int32_t,
        shift,
    );

    aptx_qmf_filter_signal_push(s1, sample0);
    let sub1 = aptx_qmf_convolution(
        s1,
        &raw const *c1 as *const int32_t,
        shift,
    );

    // SAFETY: output pointers are valid for writes exactly as required by the original function.
    unsafe {
        *low_subband_output = clip_intp2(sub0 + sub1, 23 as c_uint);
        *high_subband_output = clip_intp2(sub0 - sub1, 23 as c_uint);
    }
}

